const usernameTaken = `-- name: UsernameTaken :one
SELECT EXISTS (SELECT 1 FROM users WHERE username = ?1) AS taken
`

func (q *Queries) UsernameTaken(ctx context.Context, username string) (bool, error) {
	row := q.db.QueryRowContext(ctx, usernameTaken, username)
	var taken bool
	err := row.Scan(&taken)
	return taken, err
}

const usersInProject = `-- name: UsersInProject :many
SELECT users.id, users.username, users.display_name, users.mobile, users.password_hash, users.must_change_password, users.failed_sign_ins, users.locked_until, users.created_at, users.email FROM users JOIN user_projects ON user_projects.user_id = users.id
WHERE user_projects.project_id = ?1
ORDER BY user_projects.is_inactive, users.display_name COLLATE names
`

// Everyone in a project, the inactive last, by name (D7).
func (q *Queries) UsersInProject(ctx context.Context, projectID uuid.UUID) ([]User, error) {
	rows, err := q.db.QueryContext(ctx, usersInProject, projectID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []User
	for rows.Next() {
		var i User
		if err := rows.Scan(
			&i.ID,
			&i.Username,
			&i.DisplayName,
			&i.Mobile,
			&i.PasswordHash,
			&i.MustChangePassword,
			&i.FailedSignIns,
			&i.LockedUntil,
			&i.CreatedAt,
			&i.Email,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

